def hash_filelike(filelike):
    """
    Compute the hash of a file-like object, without loading it all into memory.
    """
    file_pos = 0
    if hasattr(filelike, "tell"):
        file_pos = filelike.tell()
    try:
        filelike.seek(0)
    except (AttributeError, UnsupportedOperation):
        pass
