        if STYLE:
            yield '<?xml-stylesheet type="text/xsl" href="/scopelist.xsl" ?>\n'
        yield '<objectlist>\n'
        for seq_no, rel_path, download_link in cursor:
            yield '<count adjust="1"/>\n'
