def unset(obj, path):
    """
    Removes the property at `path` of `obj`.
    Note:
        Only ``list``, ``dict``, or objects with a ``pop()`` method can be unset by this function.
    Args:
        obj (mixed): The object to modify.
        path (mixed): The path of the property to unset.
    Returns:
        bool: Whether the property was deleted.
    Warning:
        `obj` is modified in place.
    Example:
        >>> obj = {'a': [{'b': {'c': 7}}]}
        >>> unset(obj, 'a[0].b.c')
        True
        >>> obj
        {'a': [{'b': {}}]}
        >>> unset(obj, 'a[0].b.c')
        False
    """
    tokens = to_path_tokens(path)
    if not pyd.is_list(tokens):
        tokens = [tokens]
    last_key = pyd.last(tokens)
    if isinstance(last_key, PathToken):
        last_key = last_key.key
    target = obj
    for token in pyd.initial(tokens):
        if isinstance(token, PathToken):
            key = token.key
        else:
            key = token
        try:
            try:
                target = target[key]
            except TypeError:
                target = target[int(key)]
        except Exception:
            target = UNSET
        if target is UNSET:
            break
    did_unset = False
    if target is not UNSET:
        try:
            try:
                target.pop(last_key)
                did_unset = True
            except TypeError:
                target.pop(int(last_key))
                did_unset = True
        except Exception:
            pass
    return did_unset
PathToken = namedtuple("PathToken", ["key", "default_factory"])

