def origin_from_url(url: str) -> str:
    parts = urlparse(url)
    new = [parts[0], parts[1], "", "", "", ""]
    return urlunparse(new)
def allow_redirect_url(url: str) -> bool:
    """
    Check that a redirect target is allowed against the CORS policy.
    The "Cross-Origin Resource Sharing" configuration specifies which external hosts
    are allowed to access Open Forms. We leverage this configuration to block or allow
    redirects to external hosts.
    """
    cors = CorsMiddleware()
    origin = origin_from_url(url)
    parts = urlparse(url)
    if not cors_conf.CORS_ALLOW_ALL_ORIGINS and not cors.origin_found_in_white_lists(
        origin, parts
    ):
        return False
    else:
        return True

HEADERSIZE = 8
def nextheader(fobj):
    return struct.unpack('>4sI', fobj.read(HEADERSIZE))
class IcnsFile:
    def __init__(self, fobj):
        """
        fobj is a file-like object as an icns resource
        """
        self.dct = dct = {}
        self.fobj = fobj
        sig, filesize = nextheader(fobj)
        if sig != b'icns':
            raise SyntaxError('not an icns file')
        i = HEADERSIZE
        while i < filesize:
            sig, blocksize = nextheader(fobj)
            i += HEADERSIZE
            blocksize -= HEADERSIZE
            dct[sig] = (i, blocksize)
            fobj.seek(blocksize, 1)
            i += blocksize

HEADERSIZE = 8
def nextheader(fobj):
    return struct.unpack('>4sI', fobj.read(HEADERSIZE))
class IcnsFile:
    def __init__(self, fobj):
        """
        fobj is a file-like object as an icns resource
        """
        self.dct = dct = {}
        self.fobj = fobj
        sig, filesize = nextheader(fobj)
        if sig != b'icns':
            raise SyntaxError('not an icns file')
        i = HEADERSIZE
        while i < filesize:
            sig, blocksize = nextheader(fobj)
            if blocksize <= 0:
                raise SyntaxError('invalid block header')
            i += HEADERSIZE
            blocksize -= HEADERSIZE
            dct[sig] = (i, blocksize)
            fobj.seek(blocksize, 1)
            i += blocksize

